/**
 * History's root and Jest conformance subpath must share one declaration module
 * per release tier. Independent API Extractor rollups duplicate nominal brands;
 * these entry shims select each reviewed export set from a canonical umbrella.
 * Runtime entrypoints remain separate and are never generated by this script.
 */
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import ts from 'typescript';

/** The CLI defaults to the owner package; tests can use an isolated copy. */
const history = fileURLToPath(new URL('../packages/history/', import.meta.url));
const tiers = ['untrimmed', 'alpha', 'beta', 'public'];

/** Distinguish type-only exports to keep ESM declaration consumers strict. */
function exportedNames(filename, source) {
  const tree = ts.createSourceFile(filename, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const names = new Map();
  for (const node of tree.statements) {
    if (ts.isExportDeclaration(node)) {
      if (node.exportClause && ts.isNamedExports(node.exportClause) && node.exportClause.elements.length === 0) {
        continue;
      }
      throw new Error(`Unsupported declaration re-export in ${filename}`);
    }
    if (!node.modifiers?.some(modifier => modifier.kind === ts.SyntaxKind.ExportKeyword)) {
      continue;
    }
    const typeOnly = ts.isInterfaceDeclaration(node) || ts.isTypeAliasDeclaration(node);
    const declarations = ts.isVariableStatement(node) ? node.declarationList.declarations : [node];
    for (const declaration of declarations) {
      if (!declaration.name || !ts.isIdentifier(declaration.name)) {
        throw new Error(`Unsupported exported declaration in ${filename}`);
      }
      const name = declaration.name.text;
      const earlier = names.get(name);
      if (earlier !== undefined && earlier !== typeOnly) {
        throw new Error(`Conflicting declaration kind for ${name} in ${filename}`);
      }
      names.set(name, typeOnly);
    }
  }
  if (names.size === 0) {
    throw new Error(`Empty declaration entry: ${filename}`);
  }
  return names;
}

/** Plan both entries only after every tier has passed export parity checks. */
async function plannedHistoryShims(directory) {
  const output = path.join(directory, 'dist/api');
  const planned = [];
  for (const tier of tiers) {
    const canonicalName = `history.shared.${tier}.d.ts`;
    const canonical = exportedNames(canonicalName, await readFile(path.join(output, canonicalName), 'utf8'));
    for (const [entry, rawName] of [
      ['history', `history.root.raw.${tier}.d.ts`],
      ['history.conformance.store', `history.conformance.store.raw.${tier}.d.ts`],
    ]) {
      const exports = exportedNames(rawName, await readFile(path.join(output, rawName), 'utf8'));
      for (const [name, typeOnly] of exports) {
        if (canonical.get(name) !== typeOnly) {
          throw new Error(`${entry}/${tier}: ${name} is absent or mismatched in the canonical declaration`);
        }
      }
      const values = [...exports].filter(([, typeOnly]) => !typeOnly).map(([name]) => name).sort();
      const types = [...exports].filter(([, typeOnly]) => typeOnly).map(([name]) => name).sort();
      const target = `./history.shared.${tier}.js`;
      const lines = [
        '/** Entry-specific exports preserve one History type identity per release tier. */',
        ...(values.length ? [`export { ${values.join(', ')} } from '${target}';`] : []),
        ...(types.length ? [`export type { ${types.join(', ')} } from '${target}';`] : []),
      ];
      planned.push([path.join(output, `${entry}.${tier}.d.ts`), `${lines.join('\n')}\n`]);
    }
  }
  return planned;
}

/** Build output is generated only after the canonical report/rollup passes. */
export async function writeHistoryShims(directory = history) {
  for (const [filename, contents] of await plannedHistoryShims(directory)) {
    await writeFile(filename, contents);
  }
}

/** The check gate rejects edited, missing, or wrong-tier published shims. */
export async function verifyHistoryShims(directory = history) {
  for (const [filename, expected] of await plannedHistoryShims(directory)) {
    const actual = await readFile(filename, 'utf8');
    if (actual !== expected) {
      throw new Error(`${filename} does not match its reviewed export set and canonical release tier`);
    }
  }
}

/** The normal package build invokes this after all three reviewed extractions. */
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length === 2) {
    await writeHistoryShims();
  } else if (process.argv.length === 3 && process.argv[2] === '--check') {
    await verifyHistoryShims();
  } else {
    throw new Error('Usage: history-declaration-shims.mjs [--check]');
  }
}
